To update schema name in all MySQL {{_meta}} tables:


{noformat}mysql -u sys_usermanager -h prelive-zaf.sqldb.internal < sp_disable_schema_in_meta_table.sql{noformat}

{noformat}DELIMITER $$
DROP PROCEDURE IF EXISTS infra.sp_disable_schema_in_meta_table $$
CREATE DEFINER=`debian-sys-maint`@`localhost` PROCEDURE infra.sp_disable_schema_in_meta_table (IN db_param VARCHAR(128))
begin
    DECLARE done INT DEFAULT FALSE;
    DECLARE db_name VARCHAR(128);
    DECLARE dbsCur CURSOR FOR SELECT DISTINCT TABLE_SCHEMA FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA LIKE 'taxify_%';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET DONE = TRUE;

	IF db_param IS NULL THEN 

	    OPEN dbsCur;
	    read_loop: loop
	        FETCH dbsCur INTO db_name;
	        IF done THEN leave read_loop;
	        END IF;

			SET @SQL_UPDATE = CONCAT('UPDATE ',db_name,'._meta SET schema_structure_name = CONCAT(''_'',schema_structure_name) WHERE schema_structure_name = ''',db_name,'''');
			PREPARE renameStmt from @SQL_UPDATE;
			EXECUTE renameStmt;
			DEALLOCATE PREPARE renameStmt;

	    END loop;
	    CLOSE dbsCur;
	ELSE
			SET @SQL_UPDATE = CONCAT('UPDATE ',db_param,'._meta SET schema_structure_name = CONCAT(''_'',schema_structure_name) WHERE schema_structure_name = ''',db_param,'''');
			PREPARE renameStmt from @SQL_UPDATE;
			EXECUTE renameStmt;
			DEALLOCATE PREPARE renameStmt;
	END IF;

END $$
DELIMITER ;{noformat}

